use crate::wasi::clocks::wall_clock;

struct Node;

/// Days from 1970-01-01 to 9999-12-31 inclusive. Clamping to this keeps the
/// year at four digits, so the formatted date is always exactly 10 characters.
const MAX_DAYS: u64 = 2_932_896;

/// Converts days since the Unix epoch to a (year, month, day) civil date.
/// This is Howard Hinnant's `civil_from_days` algorithm.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

fn format_date(seconds: u64) -> String {
    let days = (seconds / 86_400).min(MAX_DAYS) as i64;
    let (y, m, d) = civil_from_days(days);
    let y = y.clamp(0, 9999);
    let s = format!("{:04}-{:02}-{:02}", y, m, d);
    if s.len() == 10 {
        s
    } else {
        String::from("1970-01-01")
    }
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        RunInfo {
            date: format_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
